	knownrebecs { Pong pong; }
	statevars { int count; }

	msgsrv initial() {
		count = 0;
		self.StartMessage();
	}

	msgsrv StartMessage() {
		// println("Ping started the game!")
		pong.PingMessage();
	}

	msgsrv PongMessage() {
		count = count + 1;
		// println("Ping received pong #" + count)
		if (count >= 10) {
			pong.StopMessage();
			// println("Ping stopped")
		} else {
			pong.PingMessage();
		}
	}
}

